import{_ as t,a,o as r,a4 as d}from"./chunks/framework.-FZumj2l.js";const m=JSON.parse('{"title":"Currencies","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/settings/currencies/index.md","filePath":"api/graphql-api/admin/settings/currencies/index.md","lastUpdated":1783327468000}'),o={name:"api/graphql-api/admin/settings/currencies/index.md"};function n(i,e,c,s,l,h){return r(),a("div",null,e[0]||(e[0]=[d('<h1 id="currencies" tabindex="-1">Currencies <a class="header-anchor" href="#currencies" aria-label="Permalink to &quot;Currencies&quot;">​</a></h1><p>The Currencies menu is the store-wide list of every currency the store can price and display amounts in, plus the actions you can take on a single currency. It mirrors the admin <strong>Settings → Currencies</strong> screen.</p><h2 id="what-this-menu-controls" tabindex="-1">What this menu controls <a class="header-anchor" href="#what-this-menu-controls" aria-label="Permalink to &quot;What this menu controls&quot;">​</a></h2><p>Each currency defines two things:</p><ol><li><strong>Identity</strong> — its ISO <code>code</code> (e.g. <code>USD</code>) and display <code>name</code> (e.g. <code>US Dollar</code>).</li><li><strong>Formatting</strong> — how a monetary amount is rendered in that currency: the <code>symbol</code>, the number of decimal places, the thousands/decimal separators, and where the symbol sits relative to the amount.</li></ol><p>A currency must exist here before a channel can use it as a base or display currency, and before exchange rates can be defined against it.</p><h2 id="when-a-row-appears-here" tabindex="-1">When a row appears here <a class="header-anchor" href="#when-a-row-appears-here" aria-label="Permalink to &quot;When a row appears here&quot;">​</a></h2><p>A currency row exists once it has been <strong>created</strong> — either seeded with the store (the default <code>USD</code>) or added via the <a href="./create.html">Create</a> mutation. There is no automatic creation; currencies are configured by an admin.</p><h2 id="field-meanings" tabindex="-1">Field meanings <a class="header-anchor" href="#field-meanings" aria-label="Permalink to &quot;Field meanings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>code</code></td><td>3-letter ISO currency code, stored uppercase and unique.</td></tr><tr><td><code>name</code></td><td>Human-readable display name.</td></tr><tr><td><code>symbol</code></td><td>The symbol shown with amounts (e.g. <code>$</code>, <code>€</code>). May be <code>null</code>.</td></tr><tr><td><code>decimal</code></td><td>Number of decimal places to render (e.g. <code>2</code> → <code>10.00</code>).</td></tr><tr><td><code>groupSeparator</code></td><td>Character that groups thousands (e.g. <code>,</code> → <code>1,000</code>).</td></tr><tr><td><code>decimalSeparator</code></td><td>Character before the decimal portion (e.g. <code>.</code> → <code>10.50</code>).</td></tr><tr><td><code>currencyPosition</code></td><td><code>left</code> or <code>right</code> — whether the symbol is a prefix (<code>$10</code>) or suffix (<code>10$</code>). May be <code>null</code>.</td></tr></tbody></table><h2 id="create-update-delete-behaviour" tabindex="-1">Create / update / delete behaviour <a class="header-anchor" href="#create-update-delete-behaviour" aria-label="Permalink to &quot;Create / update / delete behaviour&quot;">​</a></h2><ul><li><strong>Create</strong> requires <code>code</code> + <code>name</code>; the formatting fields are optional.</li><li><strong>Update</strong> changes the name and formatting fields. <strong><code>code</code> is immutable</strong> — it is not part of the update input type, so it can never be changed after creation.</li><li><strong>Delete</strong> removes a single currency; <strong>Mass delete</strong> removes several by id.</li></ul><h2 id="delete-guards" tabindex="-1">Delete guards <a class="header-anchor" href="#delete-guards" aria-label="Permalink to &quot;Delete guards&quot;">​</a></h2><p>A currency cannot be deleted if either of these is true:</p><ul><li>It is the <strong>last remaining currency</strong> — the store always needs at least one.</li><li>It is set as a <strong>channel&#39;s base currency</strong> — remove or reassign it on the channel first.</li></ul><p>Both the single <a href="./delete.html">Delete</a> and <a href="./mass-delete.html">Mass delete</a> operations enforce these guards.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="./list.html">List currencies</a></td><td><code>adminSettingsCurrencies</code> query</td></tr><tr><td><a href="./detail.html">Get a single currency</a></td><td><code>adminSettingsCurrency(id:)</code> query</td></tr><tr><td><a href="./create.html">Create a currency</a></td><td><code>createAdminSettingsCurrency</code> mutation</td></tr><tr><td><a href="./update.html">Update a currency</a></td><td><code>updateAdminSettingsCurrency</code> mutation</td></tr><tr><td><a href="./delete.html">Delete a currency</a></td><td><code>deleteAdminSettingsCurrency</code> mutation</td></tr><tr><td><a href="./mass-delete.html">Mass delete currencies</a></td><td><code>createAdminSettingsCurrencyMassDelete</code> mutation</td></tr></tbody></table><p>Permissions: <code>settings.currencies.create</code> / <code>.edit</code> / <code>.delete</code>.</p><p>All operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',20)]))}const p=t(o,[["render",n]]);export{m as __pageData,p as default};
